        <p class="intro">Choose the channel that works best for timely account updates.</p>

        <form id="notification-form" novalidate>
          <p class="required-note"><span aria-hidden="true">*</span> indicates a required field.</p>

          <div class="form-field">
            <fieldset aria-describedby="notification-hint notification-error">
              <legend>How do you prefer to receive notifications? <span aria-hidden="true">*</span></legend>
              <p id="notification-hint" class="hint">Select one option.</p>

              <div class="options">
                <div class="radio-option">
                  <input id="notification-email" type="radio" name="notification-preference" value="Email" required>
                  <label for="notification-email">Email</label>
                </div>

                <div class="radio-option">
                  <input id="notification-sms" type="radio" name="notification-preference" value="SMS" required>
                  <label for="notification-sms">SMS</label>
                </div>

                <div class="radio-option">
                  <input id="notification-push" type="radio" name="notification-preference" value="Push Notifications" required>
                  <label for="notification-push">Push Notifications</label>
                </div>
              </div>

              <p id="notification-error" class="error" aria-live="polite"></p>
            </fieldset>
          </div>

          <button type="submit">Save preference</button>
          <p id="form-status" class="status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#notification-form");
      const radios = Array.from(document.querySelectorAll('input[name="notification-preference"]'));
      const errorMessage = document.querySelector("#notification-error");
      const statusMessage = document.querySelector("#form-status");

      function setGroupValidity(isValid) {
        radios.forEach((radio) => {
          radio.setAttribute("aria-invalid", String(!isValid));
        });
      }

      function clearFeedback() {
        errorMessage.textContent = "";
        statusMessage.textContent = "";
        setGroupValidity(true);
      }

      radios.forEach((radio) => {
        radio.addEventListener("change", clearFeedback);
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selected = radios.find((radio) => radio.checked);

        if (!selected) {
          errorMessage.textContent = "Error: Choose one notification preference.";
          statusMessage.textContent = "";
          setGroupValidity(false);
          radios[0].focus();
          return;
        }

        clearFeedback();
        statusMessage.textContent = `Preference saved: ${selected.value}.`;
      });
    </script>
  </body>
